 1 | /* Assignment: first line n, second line n integer marks. Print the average with 2 decimals. */
 2 | #include <stdio.h>
 3 | int main(void) {
 4 |     int n, sum = 0, x;
 5 |     scanf("%d", &n);
 6 |     for (int i = 0; i < n; i++) { scanf("%d", &x); sum += x; }
 7 |     float avg = sum / n;
 8 |     printf("%.2f\n", avg);
 9 |     return 0;
10 | }

